script:
// =====================================================================================
//  Toyota THS-II (Prius II, "Hybrid Synergy Drive") – power-split drivetrain
//  Data and equations: J. M. Miller, "Comparative Assessment of Hybrid Vehicle Power
//  Split Transmissions", 4th VI Winter Workshop, 2005 (slide numbers in the comments).
//  Values marked (assumed) are not in the PDF; they are typical values chosen by us.
//  Sign convention everywhere: + speed = engine direction of rotation (vehicle forward);
//  + mechanical power = the machine DRIVES the gear set (motor), − = it is DRIVEN (generator).
//  + battery power = discharging.
// =====================================================================================
stage(1280, 760, "#fbfbf8");
title({hu: "Toyota THS-II (Prius II) hajtáslánc – teljesítményáramlás", en: "Toyota THS-II (Prius II) drivetrain – power flow"});
timeScale(1);                                  // real time: the car is simulated in seconds
plotWindow(30);                                // graphs show the last 30 s

// ---------------------------------------------------------------- controls
choice("drv", {hu: "Vezetés", en: "Driving"}, [
  ["demo", {hu: "Automatikus bemutató (minden üzemmód)", en: "Automatic demo (all operating modes)"}],
  ["man", {hu: "Kézi: a csúszkák vezetnek", en: "Manual: the sliders drive"}]], "demo");
choice("gear", {hu: "Választókar", en: "Gear selector"}, [["D", "D – drive"], ["N", "N – neutral"], ["R", {hu: "R – hátramenet", en: "R – reverse"}]], "D");
param("acc", {hu: "Gázpedál (vezetői igény)", en: "Accelerator pedal (driver demand)"}, 0, 100, 0, 1, "%");
param("brk", {hu: "Fékpedál", en: "Brake pedal"}, 0, 100, 0, 1, "%");
param("V", {hu: "Járműsebesség", en: "Vehicle speed"}, 0, 170, 0, 1, "km/h");
param("soc", {hu: "Akkumulátor töltöttsége (SOC)", en: "Battery state of charge (SOC)"}, 20, 100, 60, 1, "%");
param("grade", {hu: "Útemelkedés", en: "Road grade"}, -10, 15, 0, 0.5, "%");
choice("vmode", {hu: "Sebesség", en: "Speed"}, [
  ["free", {hu: "Szabad: a pedálok gyorsítják/fékezik az autót", en: "Free: the pedals accelerate / brake the car"}],
  ["hold", {hu: "Rögzített a csúszkán (görgős fékpad)", en: "Held at the slider value (roller dyno)"}]], "free");
toggle("socDyn", {hu: "A SOC változik az akkuárammal", en: "SOC follows the battery current"}, true);
param("slow", {hu: "Forgás lassítása a rajzon, 1 :", en: "Rotation slow-down in the drawing, 1 :"}, 1, 200, 40, 1, "");
button({hu: "Újraindítás", en: "Restart"}, reset);

// ---------------------------------------------------------------- data (PDF)
const K_RPM = 60 / (2 * PI);                   // rad/s → 1/min
const NS = 30, NR = 78, NPL = 24;              // sun, ring, planet teeth (slide 30)
const KPG = NR / NS;                           // basic ratio k = 78/30 = 2.6 (slide 30)
const RW = 0.3045;                             // tyre rolling radius, m (slide 23, Prius II)
const GFD = 4.0;                               // ring gear → axle ratio (slide 23, Prius II)
const ETA_FD = 0.82;                           // final drive efficiency (slides 50–60)
const ETA_MI = 0.91 * 0.94;                    // motor × inverter efficiency = 0.855 (slides 50–60)
const MV = 1313 + 80;                          // curb mass 1313 kg (slide 22) + 80 kg driver (assumed)
const CD = 0.26, AF = 2.29;                    // drag coefficient, frontal area m² (slide 22)
const R0 = 0.008, RHO = 1.225, GG = 9.81;      // rolling resistance coefficient, air density (slide 48)
const PE_MAX = 57000;                          // engine 57 kW at 5000 1/min (slide 22)
const NE_MAX = 5000 / K_RPM, NE_IDLE = 1000 / K_RPM;   // max engine speed; lowest firing speed (assumed)
const T2_MAX = 400, P2_MAX = 50000;            // MG2: 400 N·m, 50 kW (slide 25)
const T1_MAX = 75, P1_MAX = 30000;             // MG1 (S/A): 30 kW (slide 26), 75 N·m (assumed)
const WS_MAX = 6500 / K_RPM;                   // MG1 speed limit 6500 1/min (slide 47)
const UB_NOM = 201.6, CAP_AH = 6.0;            // NiMH 168 cells, 201.6 V, 6 Ah (slides 25–26)
const RI = 0.25;                               // pack internal resistance, Ω (assumed)
const PB_MAX = 21000;                          // battery power 21 kW (slide 25)
const P_AUX = 300;                             // 12 V DC/DC + electronics, W (assumed)
const JE = 0.2;                                // engine + damper inertia, kg·m² (assumed)
const F_MAXLOW = 5200;                         // full-pedal wheel force ≈ (400 + 80 N·m)·4.0·0.82/0.3045
const P_SYSRING = PE_MAX + PB_MAX * ETA_MI;    // ≈ 75 kW system power at the ring gear
const FB_MAX = 0.9 * MV * GG;                  // full brake pedal: 0.9 g deceleration force
const F_CREEP = 400, F_COAST = 250;            // creep force (D, no pedal) / coasting regen force (assumed)
const VEV_MAX = WS_MAX / KPG * RW / GFD;       // EV speed limit: MG1 would overspeed (slide 47)

// engine full-load (WOT) torque and the "optimal" operating line (slide 42, read approximately)
const N_WOT = [0, 1000, 2000, 3000, 4200, 5000], T_WOT = [60, 90, 102, 108, 111, 108.9];
const N_OPT = [1000, 1200, 1500, 2000, 2500, 3000, 3500, 4000, 4500, 5000];
const T_OPT = [60, 70, 82, 95, 102, 106, 108, 109, 109.5, 108.9];
function interp1(xs, ys, x) {                  // linear interpolation in a table
  if (x <= xs[0]) return ys[0];
  for (let i = 1; i < xs.length; i++) if (x <= xs[i]) return lerp(ys[i - 1], ys[i], (x - xs[i - 1]) / (xs[i] - xs[i - 1]));
  return ys[ys.length - 1];
}
function teWot(w) { return interp1(N_WOT, T_WOT, w * K_RPM); }
function nOptRad(pw) {                         // engine speed (rad/s) on the optimal line for power pw (W)
  const pts = N_OPT.map((n, i) => T_OPT[i] * n / K_RPM);
  return interp1(pts, N_OPT, pw) / K_RPM;
}
function tFric(w) { return w > 0.5 ? 8 + 0.004 * w * K_RPM : 0; }   // drag torque of an unfuelled engine, N·m (assumed)
function bsfcOf(w, te) {                       // fuel consumption g/kWh, best ≈ 215 near the optimal line (slide 42)
  const fr = clamp(te / max(teWot(w), 1), 0.05, 1);
  return 215 + 260 * pow(1 - fr, 2) + 0.006 * abs(w * K_RPM - 2600);
}
function elP(pm) { return pm > 0 ? pm / ETA_MI : pm * ETA_MI; }    // mechanical → electric power (losses)
function mechP(pe) { return pe > 0 ? pe * ETA_MI : pe / ETA_MI; }  // electric → mechanical power
function uoc(s) { return 186 + 30 * s; }                           // open-circuit voltage ≈ 201.6 V mid-SOC (assumed)
function pDisMax(s) { return PB_MAX * clamp((s - 0.40) / 0.08, 0, 1); }   // no discharge below 40 % SOC
function pChgMax(s) { return PB_MAX * clamp((0.85 - s) / 0.05, 0, 1); }   // no charging above 85 % SOC

// ---------------------------------------------------------------- state
let vv = 0;                                    // vehicle speed, m/s (+ forward, − reverse)
let we = 0, teAct = 0;                         // engine speed rad/s, engine torque N·m
let eng = "off";                               // engine state: off | crank | run | cut (spinning without fuel)
let socS = P.soc / 100;                        // state of charge 0…1
let pTrim = 0, lastPb = 0, lastLoss = 0;       // engine power correction; electric losses of the last step
let pEngF = 0;                                 // smoothed engine power target, W
let lastVset = P.V, lastSocSet = P.soc, syncT = 0;
let tDemo = 0, demoSeg = -1;
let angC = 0, angS = 0, crankAng = 0;          // drawn angles (slowed down): carrier = engine, sun = MG1
const fp = {e: 0, g: 0, m: 0, o: 0, ax: 0, b: 0, eg: 0, em: 0};   // positions of the moving power arrows
let op = {};                                   // everything computed in the last physics step (for drawing)

// automatic demo: [duration s, accelerator %, brake %, gear, SOC set at start (or null), note]
const DEMO = [
  [3, 0, 40, "D", 60],     // READY
  [8, 18, 0, "D", null],   // electric launch (Batt-EV)
  [9, 30, 0, "D", null],   // engine start, normal power split
  [7, 100, 0, "D", null],  // kick-down: power boost
  [12, 20, 0, "D", null],  // high-speed cruise: negative split
  [4, 0, 0, "D", null],    // pedal released: fuel cut, light regeneration
  [11, 0, 35, "D", null],  // regenerative braking to a stop
  [7, 0, 40, "D", 43],     // low SOC at standstill: battery charging
  [9, 25, 0, "D", null],   // drive off: power split + charging
  [7, 0, 45, "D", 60],     // stop (SOC set back to 60 %)
  [6, 20, 0, "R", null],   // reverse
  [3, 0, 50, "R", null],   // stop
  [2, 0, 50, "D", null]];  // back to D
const DEMO_T = DEMO.reduce((s, d) => s + d[0], 0);

function demoStep(dt) {
  tDemo = (tDemo + dt) % DEMO_T;
  let t0 = 0, i = 0;
  while (i < DEMO.length - 1 && tDemo >= t0 + DEMO[i][0]) { t0 += DEMO[i][0]; i++; }
  const d = DEMO[i];
  if (i !== demoSeg) {                         // a new segment begins
    demoSeg = i;
    if (P.gear !== d[3]) setParam("gear", d[3]);
    if (d[4] !== null) { socS = d[4] / 100; setParam("soc", d[4]); lastSocSet = d[4]; }
  }
  const ramp = (cur, tgt) => cur + clamp(tgt - cur, -60 * dt, 60 * dt);   // pedals move at 60 %/s
  const a1 = ramp(P.acc, d[1]), b1 = ramp(P.brk, d[2]);
  if (abs(a1 - P.acc) > 1e-6) setParam("acc", a1);
  if (abs(b1 - P.brk) > 1e-6) setParam("brk", b1);
}

// ---------------------------------------------------------------- physics
update(dt => {
  if (P.drv === "demo") demoStep(dt);
  const gearS = P.gear, dirG = gearS === "R" ? -1 : 1;
  // the user moved the speed or SOC slider → take it over
  if (abs(P.V - lastVset) > 0.6) { vv = dirG * P.V / 3.6; lastVset = P.V; }
  if (abs(P.soc - lastSocSet) > 0.6) { socS = P.soc / 100; lastSocSet = P.soc; }
  const hold = P.vmode === "hold" && P.drv !== "demo";
  if (hold) vv = dirG * (gearS === "R" ? min(P.V, 25) : P.V) / 3.6;

  const acc = P.acc / 100, brk = P.brk / 100, vAbs = abs(vv);
  const sgnMove = abs(vv) > 0.01 ? sign(vv) : dirG;
  const wr = vv / RW * GFD;                    // ring gear = MG2 speed (MG2 sits on the ring), rad/s
  // 1) road load (slide 48): rolling + aerodynamic + grade
  const alphaR = atan(P.grade / 100);
  const fRoll = R0 * MV * GG * cos(alphaR), fAero = 0.5 * RHO * CD * AF * vv * vv, fGrade = MV * GG * sin(alphaR);

  // 2) driver request → wheel force (+ forward)
  let fReq = 0, braking = false;
  const fMaxDrive = min(F_MAXLOW, P_SYSRING * ETA_FD / max(vAbs, 1));
  if (brk > 0.005) { braking = true; fReq = -sgnMove * brk * FB_MAX; }
  else if (gearS === "N") fReq = 0;
  else if (acc > 0.005) {
    fReq = dirG * acc * fMaxDrive;
    if (gearS === "R") fReq *= clamp((25 - vAbs * 3.6) / 5, 0, 1);   // reverse speed limiter (slide 37 note)
  } else if (sign(vv) !== dirG && vAbs > 0.01) fReq = dirG * F_CREEP;                 // rolling back: MG2 resists
  else if (vAbs < 2) fReq = dirG * F_CREEP * clamp(1 - vAbs / 2, 0, 1);              // creep
  else { braking = true; fReq = -sgnMove * F_COAST; }                  // lifted pedal: gentle regeneration
  // regenerative share of a braking request (fades out below 10 km/h, none in N)
  const kFade = clamp((vAbs * 3.6 - 3) / 7, 0, 1);
  const fDlReq = braking ? (gearS === "N" ? 0 : fReq * kFade) : fReq;
  // 3) wheel force → ring gear torque (final drive losses depend on the power direction)
  const tRingReq = fDlReq * vv >= 0 ? fDlReq * RW / (GFD * ETA_FD) : fDlReq * RW * ETA_FD / GFD;
  const pRingReq = tRingReq * wr;

  // 4) engine on/off strategy (with hysteresis)
  const socP = socS * 100, running = eng === "run" || eng === "crank";
  const pOn = clamp(4000 + 800 * (socP - 50), 2500, 20000);   // EV allowed up to 4 kW at 50 % … 20 kW at 70 % SOC
  let want = false;
  if (gearS === "D") {
    if (!braking) {
      if (pRingReq > (running ? 0.7 * pOn : pOn)) want = true;               // driver needs more than EV can give
      if (tRingReq > (running ? 0.45 : 0.55) * T2_MAX) want = true;         // high torque demand (e.g. hill start)
      if (vAbs > VEV_MAX * (running ? 0.90 : 0.95)) want = true;            // above the EV speed limit
      if (socP < (running ? 52 : 45)) want = true;                          // battery must be charged
    } else if (vAbs < 0.3 && socP < (running ? 52 : 45)) want = true;       // standing still: charge
  } else if (gearS === "R" && vAbs < 0.3 && socP < (running ? 52 : 45)) want = true;

  // MG1 speed limit ±6500 1/min restricts the engine speed: ωs = (1+k)·ωc − k·ωr (slide 29)
  const weLo = max(0, (KPG * wr - WS_MAX) / (1 + KPG)), weHi = max(0, (KPG * wr + WS_MAX) / (1 + KPG));
  if (eng === "off" && (want || weLo > 1)) eng = want ? "crank" : "cut";
  else if (eng === "crank" && we >= 0.95 * NE_IDLE) eng = "run";
  else if (eng === "crank" && !want) eng = "cut";
  else if (eng === "run" && !want) eng = "cut";
  else if (eng === "cut" && want) eng = we > 0.9 * NE_IDLE ? "run" : "crank";
  else if (eng === "cut" && we < 0.5 && weLo < 0.5) eng = "off";

  // 5) engine target operating point
  const pDis = pDisMax(socS), pChgL = pChgMax(socS);
  let weT = 0, teT = 0, pEngT = 0;
  if (eng === "run") {
    const pChg = clamp(800 * (60 - socP), -8000, 8000);           // SOC controller: target 60 %, 0.8 kW per %
    const excess = max(0, lastPb - pDis) - max(0, -pChgL - lastPb);
    pTrim = clamp(pTrim + excess * dt * 2 - pTrim * dt * 3, -8000, 8000);   // anti-windup: leaks away quickly
    // engine covers: road demand + battery charging + losses of the electric path (MG1 → MG2) + aux
    const pRaw = clamp(max(0, pRingReq) + pChg + lastLoss + pTrim, 4000, PE_MAX);   // ≥ 4 kW when running
    pEngF += (pRaw - pEngF) * min(1, dt / 0.4);                   // the controller moves the engine smoothly (0.4 s)
    pEngT = pEngF;
    const lo = max(weLo, NE_IDLE), hi = max(min(weHi, NE_MAX), lo);
    weT = clamp(nOptRad(pEngT), lo, hi);                          // optimal line, inside the MG1 speed window
    teT = clamp(pEngT / weT, 0, teWot(weT));
  } else if (eng === "crank") {
    pEngF = 4000; pTrim = 0; weT = clamp(NE_IDLE, weLo, max(weHi, weLo)); teT = -tFric(we); }
  else if (eng === "cut") { pEngF = 4000; pTrim = 0; weT = weLo; teT = -tFric(we); }
  // engine speed is steered by MG1 (rate-limited), torque follows with a 0.15 s lag
  const rate = (eng === "crank" ? 1600 : 1200) / K_RPM;           // 1/min per s → rad/s²
  let weN = we + clamp(weT - we, -rate * dt, rate * dt);
  weN = clamp(weN, weLo, max(weHi, weLo));
  if (eng === "off") weN = 0;
  const alphaE = clamp((weN - we) / dt, -2000, 2000);
  we = weN;
  teAct += (teT - teAct) * min(1, dt / 0.15);
  if (eng === "off") teAct = 0;

  // 6) torques in the power-split device (slides 30–32, lossless gears)
  const ws = (1 + KPG) * we - KPG * wr;                           // sun = MG1 speed
  const tSplit = teAct - JE * alphaE;                             // carrier torque left after accelerating the engine
  const t1Lim = min(T1_MAX, P1_MAX / max(abs(ws), 1));
  const t1 = clamp(-tSplit / (1 + KPG), -t1Lim, t1Lim);           // MG1 reaction torque on the sun
  const tE2R = -KPG * t1;                                         // engine torque reaching the ring: k/(k+1)·T_e
  const t2Lim = min(T2_MAX, P2_MAX / max(abs(wr), 1));
  let t2 = clamp(tRingReq - tE2R, -t2Lim, t2Lim);                 // MG2 supplies the rest (slide 32)
  const p1 = t1 * ws, pe1 = elP(p1);
  let p2 = t2 * wr, pe2 = elP(p2), pb = pe1 + pe2 + P_AUX;
  // 7) battery power limits: MG2 is cut back (less wheel torque or less regeneration)
  if (abs(wr) > 1 && (pb > pDis || pb < -pChgL)) {
    const pe2a = (pb > pDis ? pDis : -pChgL) - pe1 - P_AUX;
    const t2a = clamp(mechP(pe2a) / wr, -t2Lim, t2Lim);
    if (abs(t2a) < abs(t2) || sign(t2a) !== sign(t2)) { t2 = t2a; p2 = t2 * wr; pe2 = elP(p2); pb = pe1 + pe2 + P_AUX; }
  }
  lastPb = pb;
  lastLoss = (pe1 - p1) + (pe2 - p2) + P_AUX;                    // W lost in MG1, MG2, inverters + aux
  const tRing = tE2R + t2, pRing = tRing * wr;
  const fDl = pRing >= 0 ? tRing * GFD * ETA_FD / RW : tRing * GFD / (RW * ETA_FD);   // driveline wheel force

  // 8) friction brakes take whatever regeneration could not
  const fRegen = max(0, -fDl * sgnMove);                          // driveline force opposing the motion
  const fFric = brk > 0.005 ? max(0, brk * FB_MAX - fRegen) : 0;

  // 9) vehicle motion (5 % added for rotating masses, assumed)
  let fNet;
  if (vAbs < 0.03) {
    const fPush = fDl - fGrade, fHold = fRoll + brk * FB_MAX;     // standing still: static friction holds the car
    fNet = abs(fPush) <= fHold ? 0 : fPush - sign(fPush) * fHold;
    if (fNet === 0) vv = 0;                                       // held: the car stands still
  } else fNet = fDl - fGrade - sign(vv) * (fRoll + fAero + fFric);
  const aVeh = fNet / (MV * 1.05);
  if (!hold) {
    const vN = vv + aVeh * dt;
    vv = (vv !== 0 && sign(vN) !== sign(vv) && (fFric > 0 || abs(fDl) < fRoll + fFric + 50)) ? 0 : vN;
  }

  // 10) battery current from slide 71: P = I·(Uoc − I·Ri)
  const u0 = uoc(socS);
  const ib = (u0 - sqrt(max(0, u0 * u0 - 4 * pb * RI))) / (2 * RI);
  if (P.socDyn) socS = clamp(socS - ib * dt / (CAP_AH * 3600), 0.2, 1);

  // 11) fuel
  const pe = eng === "run" ? teAct * we : 0;
  const bsfc = pe > 100 ? bsfcOf(we, teAct) : 0;
  const fuelGs = pe * bsfc / 3.6e6;                                // g/s
  const pFuel = fuelGs * 43000;                                    // gasoline 43 kJ/g

  // 12) operating mode (names follow slides 35–41)
  let mode;
  if (eng === "crank") mode = "start";
  else if (eng === "run") {
    if (vAbs < 0.3) mode = "chargeStop";
    else if (p1 > 300 && ws < 0) mode = "negSplit";
    else if (pb > 2000) mode = "boost";
    else if (pb < -2000) mode = "splitChg";
    else mode = "split";
  } else {
    const drv = fDl * sgnMove;
    if (drv < -40) mode = we > 1 ? "cutRegen" : "regen";
    else if (fFric > 30 && vAbs > 0.05) mode = "friction";
    else if (we > 1) mode = "cut";
    else if (p2 * sgnMove * sign(wr || 1) > 150 && vAbs > 0.02) mode = vv < 0 ? "reverse" : "ev";
    else if (fDl * dirG > 30 && vAbs < 0.03) mode = "ev";
    else mode = "ready";
  }
  const limited = !braking && fReq * dirG > 50 && fDl * dirG < 0.93 * fReq * dirG;

  // 13) drawn angles and power-arrow positions (integrated so nothing jumps)
  const kv = 1 / P.slow;
  angC += we * kv * dt; angS += ws * kv * dt; crankAng += we * kv * dt;
  const adv = (key, pw) => { if (abs(pw) > 50) fp[key] += sign(pw) * (25 + 2.2 * min(abs(pw) / 1000, 60)) * dt; };
  adv("e", teAct * we); adv("g", p1); adv("m", p2); adv("o", pRing); adv("ax", fDl * vv);
  adv("b", pb); adv("eg", pe1); adv("em", pe2);

  op = {wr, ws, t1, t2, tE2R, tRing, p1, p2, pe1, pe2, pb, ib, ub: u0 - ib * RI, u0, pDis, pChgL,
    fReq, fDl, fFric, fRoll, fAero, fGrade, aVeh, pe, bsfc, fuelGs, pFuel, mode, limited, braking,
    alphaE, tSplit, weT, pEngT, hold, kFade};

  // 14) keep the speed and SOC sliders showing the live values
  syncT += dt;
  if (syncT > 0.1) {
    syncT = 0;
    const vk = round(vAbs * 3.6);
    if (!hold && vk !== P.V) { setParam("V", vk); lastVset = vk; }
    const sk = round(socS * 100);
    if (sk !== P.soc) { setParam("soc", sk); lastSocSet = sk; }
  }
});

// ---------------------------------------------------------------- drawing helpers
const COL = {eng: "#d1495b", mg1: "#2f6fd6", mg2: "#1f9e89", bat: "#e09f1f", mech: "#2e7d32", elec: "#f08c00",
  steel: "#8a94a6", dark: "#3b4252", panel: "#ffffff", fric: "#c0392b"};
const MODES = {
  ready: [{hu: "Álló helyzet – READY", en: "Standstill – READY"}, "#7c8696",
    {hu: "A motor áll, MG1 és MG2 áll. Csak a segédüzem (12 V) fogyaszt az akkumulátorból.",
     en: "Engine off, MG1 and MG2 at rest. Only the auxiliaries (12 V) draw from the battery."}],
  ev: [{hu: "Batt-EV: tisztán elektromos hajtás", en: "Batt-EV: pure electric drive"}, COL.mg2,
    {hu: "Motor KI, generátor nem dolgozik (37. dia). Akku → inverter → MG2 → gyűrűs kerék → kerekek. MG1 szabadon hátrafelé forog: n_s = −k·n_r.",
     en: "Engine OFF, generator unused (slide 37). Battery → inverter → MG2 → ring gear → wheels. MG1 freewheels backwards: n_s = −k·n_r."}],
  reverse: [{hu: "Hátramenet (Batt-EV)", en: "Reverse (Batt-EV)"}, COL.mg2,
    {hu: "MG2 visszafelé forog, a motor áll. A sebességet a szoftver korlátozza (37. dia).",
     en: "MG2 turns backwards, the engine is off. Speed is limited by software (slide 37)."}],
  regen: [{hu: "Visszatápláló (regeneratív) fékezés", en: "Regenerative braking"}, COL.mech,
    {hu: "A kerekek hajtják MG2-t, ami generátorként tölti az akkut. A motor áll. A maradék fékerőt a súrlódó fék adja.",
     en: "The wheels drive MG2 as a generator and it charges the battery. Engine off. Friction brakes add the rest."}],
  friction: [{hu: "Csak súrlódó fék", en: "Friction brakes only"}, COL.fric,
    {hu: "Nincs visszatáplálás (akku tele, nagyon kis sebesség vagy N állás): a mozgási energia hővé alakul.",
     en: "No regeneration (battery full, very low speed or N): kinetic energy turns into heat."}],
  start: [{hu: "Motorindítás: MG1 indítómotorként forgat", en: "Engine start: MG1 cranks the engine"}, COL.mg1,
