function wrapTxt(s, n) {                       // break a sentence into lines of at most n characters
  s = s.replace(/\(slide (\d+)\)/g, "(slide\u00a0$1)").replace(/(\d+)\. dia\)/g, "$1.\u00a0dia)");   // keep "(slide 39)" together
  const words = s.split(" "), out = [];
  let cur = "";
  for (const w of words) { if ((cur + " " + w).trim().length > n) { out.push(cur); cur = w; } else cur = (cur + " " + w).trim(); }
  if (cur) out.push(cur);
  return out.join("\n");
}
function kw(pw) { return fmt(pw / 1000, 1) + " kW"; }
function rpmTxt(w) { return fmt(w * K_RPM, 0) + " 1/min"; }
function card(x, y, w, h, head, col, lines) {   // information card
  rect(x, y, w, h, {fill: "rgba(255,255,255,0.93)", stroke: col, lw: 1.5, radius: 6});
  rect(x, y, w, 19, {fill: col, stroke: null, radius: 6});
  text(head, x + 6, y + 14, {size: 12, bold: true, color: "#fff"});
  lines.forEach((ln, i) => text(ln, x + 6, y + 34 + i * 15, {size: 12, color: COL.dark}));
}
// a shaft seen from the side: lines on its surface move across it as it turns (front half only)
function shaftH(x1, x2, yc, hw, col, angNow) {
  rect(x1, yc - hw, x2 - x1, 2 * hw, {fill: col, stroke: "rgba(0,0,0,0.35)", lw: 1});
  for (let j = 0; j < 4; j++) {
    const ph = angNow + j * PI / 2;
    if (cos(ph) > 0) line(x1 + 1, yc - hw * 0.92 * sin(ph), x2 - 1, yc - hw * 0.92 * sin(ph), {stroke: "rgba(255,255,255,0.75)", lw: 2, alpha: cos(ph)});
  }
}
function shaftV(xc, y1, y2, hw, col, angNow) {
  rect(xc - hw, y1, 2 * hw, y2 - y1, {fill: col, stroke: "rgba(0,0,0,0.35)", lw: 1});
  for (let j = 0; j < 4; j++) {
    const ph = angNow + j * PI / 2;
    if (cos(ph) > 0) line(xc + hw * 0.92 * sin(ph), y1 + 1, xc + hw * 0.92 * sin(ph), y2 - 1, {stroke: "rgba(255,255,255,0.75)", lw: 2, alpha: cos(ph)});
  }
}
function gearPts(cx, cy, rp, n, a0, md, internal) {   // tooth outline; md = module in px
  const pts = [], pa = 2 * PI / n;
  const rTip = internal ? rp - md : rp + md, rRoot = internal ? rp + 1.25 * md : rp - 1.25 * md;
  for (let i = 0; i < n; i++) {
    const a = a0 + i * pa;
    for (const [f, r] of [[-0.3, rRoot], [-0.14, rTip], [0.14, rTip], [0.3, rRoot]])
      pts.push([cx + r * cos(a + f * pa), cy - r * sin(a + f * pa)]);
  }
  return pts;
}
function badge(x, y, pm, idleTxt) {           // MOTOR / GENERATOR label
  const isM = pm > 150, isG = pm < -150;
  const s = isM ? {hu: "MOTOR", en: "MOTOR"} : isG ? {hu: "GENERÁTOR", en: "GENERATOR"} : idleTxt;
  text(s, x, y, {size: 11, bold: true, align: "center", color: "#fff", bg: isM ? COL.elec : isG ? COL.mech : COL.steel});
}
function pflow(path, key, pw, col, lab, lx, ly) {   // moving power arrows + label (hidden when ~0)
  if (abs(pw) < 60) return;
  flow(path, {pos: fp[key], dir: sign(pw) || 1, line: false, color: col, size: 9, spacing: 24, alpha: clamp(0.35 + abs(pw) / 8000, 0, 1)});
  if (lab) text(kw(abs(pw)), lx, ly, {size: 11, bold: true, color: col, align: "center", bg: "rgba(251,251,248,0.85)"});
}

// ---------------------------------------------------------------- drawing
draw(t => {
  if (op.mode === undefined) return;
  const isHu = lang() === "hu";
  const wr = op.wr, ws = op.ws, kv = 1 / P.slow;
  const cx0 = 600, cy0 = 395;                  // centre of the power-split device
  const md = 3;                                // gear module in px (pitch radius = md·N/2)
  const rS = md * NS / 2, rPl = md * NPL / 2, rRi = md * NR / 2, rRo = 133, rCg = 30;
  const angR = (angC * (NS + NR) - angS * NS) / NR;   // ring angle from the planetary equation (slide 29)
  const angWh = angR / GFD;                    // axle / wheel angle

  // ---------- 1. engine (inline 4, side view with pistons) ----------
  rect(30, 235, 220, 135, {fill: "#e9ecf1", stroke: COL.dark, lw: 2, radius: 6});      // block + head
  rect(30, 370, 220, 85, {fill: "rgba(233,236,241,0.6)", stroke: COL.dark, lw: 2, radius: 6});  // crankcase
  const ofs = [0, PI, PI, 0], fire = [0, 3 * PI, PI, 2 * PI];    // crank pins; firing order 1-3-4-2
  for (let i = 0; i < 4; i++) {
    const xc = 65 + i * 50, th = crankAng + ofs[i], rc = 20, lr = 62;
    const pinX = xc + rc * sin(th), pinY = cy0 - rc * cos(th);
    const pistY = cy0 - (rc * cos(th) + sqrt(lr * lr - pow(rc * sin(th), 2)));
    rect(xc - 19, 262, 38, 110, {fill: "#f7f8fa", stroke: COL.steel, lw: 1.5});      // cylinder bore
    const psi = mod(crankAng - fire[i], 4 * PI);
    if (eng === "run" && psi < 0.7 * PI) rect(xc - 18, 263, 36, max(0, pistY - 14 - 263), {fill: "#ff9f1c", stroke: null, alpha: 0.85 * (1 - psi / (0.7 * PI))});
    line(pinX, pinY, xc, pistY, {stroke: COL.dark, lw: 5});                           // connecting rod
    rect(xc - 17, pistY - 14, 34, 24, {fill: "#b8c0cc", stroke: COL.dark, lw: 1.5, radius: 3});   // piston
    circle(pinX, pinY, 6, {fill: COL.eng, stroke: COL.dark, lw: 1});
    circle(xc, 250, 4, {fill: eng === "run" && psi < 0.15 * PI ? "#ffd60a" : "#c9ced6", stroke: null});   // spark plug
  }
  shaftH(32, 250, cy0, 6, COL.eng, crankAng);                                         // crankshaft
  text({hu: "Belsőégésű motor (ICE)", en: "Engine (ICE)"}, 140, 228, {size: 13, bold: true, color: COL.eng, align: "center"});

  // ---------- 2. shafts into the gear set ----------
  shaftH(250, cx0 - 140, cy0, 7, COL.eng, angC);                                     // engine → carrier
  rect(262, cy0 - 38, 12, 76, {fill: "#c9ced6", stroke: COL.dark, lw: 1, radius: 3}); // damper / flywheel
  shaftH(cx0 + 140, 800, cy0, 10, COL.mg2, angR);                                    // ring → MG2 rotor

  // ---------- 3. power-split device, face view ----------
  circle(cx0, cy0, 141, {fill: COL.mg2, stroke: COL.dark, lw: 1, alpha: 0.9});
  polygon(gearPts(cx0, cy0, rRo, 90, angR, md, false), {fill: "#3fb39e", stroke: COL.dark, lw: 0.8});  // outer (counter drive) teeth
  circle(cx0, cy0, rRo - 4, {fill: "#2fa58f", stroke: null});
  polygon(gearPts(cx0, cy0, rRi, NR, angR, md, true), {fill: "#fbfbf8", stroke: COL.dark, lw: 0.8});   // internal teeth
  // carrier plate behind the planets
  circle(cx0, cy0, rS + rPl + 14, {fill: "rgba(209,73,91,0.18)", stroke: "rgba(209,73,91,0.5)", lw: 1});
  polygon(gearPts(cx0, cy0, rS, NS, angS, md, false), {fill: "#5b8def", stroke: COL.dark, lw: 1});    // sun
  for (let i = 0; i < 4; i++) {
    const phi = angC + i * PI / 2, pcx = cx0 + (rS + rPl) * cos(phi), pcy = cy0 - (rS + rPl) * sin(phi);
    const angP = phi + PI + PI / NPL - (NS / NPL) * (angS - phi);   // planet angle from rolling on the sun
    polygon(gearPts(pcx, pcy, rPl, NPL, angP, md, false), {fill: "#f2c14e", stroke: COL.dark, lw: 1});
    line(pcx, pcy, pcx + 0.6 * rPl * cos(angP), pcy - 0.6 * rPl * sin(angP), {stroke: COL.dark, lw: 2});  // planet mark
    line(cx0 + (rS + 6) * cos(phi), cy0 - (rS + 6) * sin(phi), pcx, pcy, {stroke: COL.eng, lw: 7, alpha: 0.85});  // carrier arm
    circle(pcx, pcy, 7, {fill: COL.eng, stroke: COL.dark, lw: 1});                     // planet pin
  }
  line(cx0, cy0, cx0 + 0.7 * rS * cos(angS), cy0 - 0.7 * rS * sin(angS), {stroke: "#fff", lw: 3});   // sun mark
  // counter drive gear (to the final drive)
  const cgx = cx0, cgy = cy0 + rRo + rCg, angCg = -PI / 2 + PI + PI / 20 - (90 / 20) * (angR + PI / 2);
  polygon(gearPts(cgx, cgy, rCg, 20, angCg, md, false), {fill: "#9aa5b8", stroke: COL.dark, lw: 1});
  circle(cgx, cgy, 6, {fill: COL.dark});
  // MG1 shaft comes towards the viewer from the sun and goes up to MG1 (drawn transparent over the gears)
  shaftV(cx0, 205, cy0, 8, COL.mg1, angS);
  circle(cx0, cy0, 11, {fill: COL.mg1, stroke: "#fff", lw: 2});
  text({hu: "S napkerék = MG1", en: "S sun = MG1"}, cx0 - 150, cy0 - 120, {size: 12, bold: true, color: COL.mg1, align: "right"});
  text({hu: "C bolygókar = motor", en: "C carrier = engine"}, cx0 - 150, cy0 - 104, {size: 12, bold: true, color: COL.eng, align: "right"});
  text({hu: "R gyűrűs kerék = MG2", en: "R ring = MG2"}, cx0 - 150, cy0 - 88, {size: 12, bold: true, color: "#178a75", align: "right"});

  // ---------- 4. MG1 (top) and MG2 (right) ----------
  rect(550, 100, 100, 105, {fill: "#dfe7f7", stroke: COL.mg1, lw: 2, radius: 6});
  for (let j = 0; j < 6; j++) { rect(553, 108 + j * 15, 12, 9, {fill: "#c47a2c", stroke: null}); rect(635, 108 + j * 15, 12, 9, {fill: "#c47a2c", stroke: null}); }
  shaftV(cx0, 110, 198, 26, "#4b7fd8", angS);                                        // MG1 rotor
  text("MG1", cx0, 96, {size: 13, bold: true, color: COL.mg1, align: "center"});
