  rect(800, 330, 105, 130, {fill: "#dcf1ec", stroke: COL.mg2, lw: 2, radius: 6});
  for (let j = 0; j < 6; j++) { rect(808 + j * 16, 333, 10, 12, {fill: "#c47a2c", stroke: null}); rect(808 + j * 16, 445, 10, 12, {fill: "#c47a2c", stroke: null}); }
  shaftH(806, 899, cy0, 40, "#2ab39a", angR);                                       // MG2 rotor
  text("MG2", 805, 323, {size: 13, bold: true, color: "#178a75", align: "left"});
  badge(852, 476, op.p2, {hu: "áll / szabad", en: "idle"});

  // ---------- 5. final drive, axle, wheels, brakes ----------
  shaftV(cgx, cgy + 6, 632, 6, "#9aa5b8", angR * 90 / 20);
  shaftH(330, 870, 650, 7, "#9aa5b8", angWh);                                       // half-shafts
  rect(cgx - 30, 630, 60, 42, {fill: "#c9ced6", stroke: COL.dark, lw: 1.5, radius: 6});
  text({hu: "Diff.", en: "Diff."}, cgx, 656, {size: 11, bold: true, align: "center", color: COL.dark});
  const fricGlow = clamp(op.fFric * abs(vv) / 30000, 0, 1);
  for (const [xd, xt] of [[340, 300], [852, 870]]) {
    rect(xd, 612, 8, 76, {fill: fricGlow > 0.02 ? COL.fric : "#9aa5b8", stroke: COL.dark, lw: 1, alpha: 0.4 + 0.6 * fricGlow});
    rect(xt, 595, 30, 110, {fill: "#2b2d33", stroke: "#000", lw: 1, radius: 8});
    for (let j = 0; j < 8; j++) {                                                 // tread blocks moving with the wheel
      const ph = angWh * 3 + j * PI / 4;
      if (cos(ph) > 0) rect(xt + 3, 650 - 52 * sin(ph) - 2, 24, 4, {fill: "#6b7280", stroke: null, alpha: cos(ph)});
    }
  }
  text({hu: "Végáttétel i = 4,0  η = 0,82", en: "Final drive i = 4.0  η = 0.82"}, cgx - 40, 692, {size: 11, color: COL.dark, align: "right"});

  // ---------- 6. battery, PCU, cables ----------
  rect(690, 95, 110, 110, {fill: "#fff4e0", stroke: COL.elec, lw: 2, radius: 6});
  text("PCU", 745, 116, {size: 13, bold: true, color: COL.elec, align: "center"});
  const udc = max(op.ub, min(500, op.ub + 300 * max(abs(wr) / 600, abs(op.pe2) / 40000, abs(ws) / 650)));  // boost converter 2.5× (slide 26)
  text((isHu ? "inverterek +\nfeszültségnövelő\n" : "inverters +\nboost converter\n") + "U_dc = " + fmt(udc, 0) + " V", 745, 134, {size: 11, color: COL.dark, align: "center"});
  rect(840, 80, 95, 150, {fill: "#fff8e6", stroke: COL.bat, lw: 2, radius: 6});
  rect(855, 72, 18, 8, {fill: COL.bat}); rect(902, 72, 18, 8, {fill: COL.bat});
  const socNow = socS;
  rect(848, 100, 14, 122, {fill: "#eee", stroke: COL.dark, lw: 1});
  rect(848, 100 + 122 * (1 - socNow), 14, 122 * socNow, {fill: socNow < 0.45 ? COL.fric : socNow > 0.8 ? COL.mg1 : COL.mech, stroke: null});
  text((isHu ? "HV akku\nNiMH\n" : "HV battery\nNiMH\n") + fmt(op.ub, 1) + " V\n" + fmt(op.ib, 1) + " A\nSOC " + fmt(socNow * 100, 1) + " %", 900, 98, {size: 11, color: COL.dark, align: "center"});
  line(800, 150, 840, 150, {stroke: COL.elec, lw: 4});                              // battery ↔ PCU (DC)
  for (let j = -1; j <= 1; j++) line(650, 150 + j * 5, 690, 150 + j * 5, {stroke: COL.elec, lw: 2});   // PCU ↔ MG1 (3 phases)
  for (let j = -1; j <= 1; j++) polyline([[745 + j * 5, 205], [745 + j * 5, 270 + j * 5], [882 + j * 5, 270 + j * 5], [882 + j * 5, 330]], {stroke: COL.elec, lw: 2});
  pflow([[838, 140], [802, 140]], "b", op.pb, COL.elec, true, 820, 128);
  pflow([[688, 140], [652, 140]], "eg", op.pe1, COL.elec, true, 670, 128);
  pflow([[735, 208], [735, 260], [872, 260], [872, 328]], "em", op.pe2, COL.elec, true, 805, 254);

  // ---------- 7. mechanical power arrows on the shafts ----------
  pflow([[285, cy0 - 18], [455, cy0 - 18]], "e", teAct * we, COL.mech, true, 380, cy0 - 30);
  pflow([[cx0 + 22, 212], [cx0 + 22, 252]], "g", -op.p1, COL.mech, true, cx0 + 52, 240);   // + = from gear set to MG1
  pflow([[745, cy0 - 22], [798, cy0 - 22]], "m", -op.p2, COL.mech, true, 770, cy0 - 30);    // + = from ring to MG2
  pflow([[cgx + 18, 595], [cgx + 18, 628]], "o", op.tRing * wr, COL.mech, false);
