      : eng === "off" ? (isHu ? "ÁLL" : "OFF") : eng === "crank" ? (isHu ? "INDÍTÁS (MG1 forgatja)" : "CRANKING (MG1 drives it)") : (isHu ? "forog, üzemanyag nélkül" : "turning, no fuel")]);
  card(330, 95, 210, 82, {hu: "MG1 ↔ napkerék (S)", en: "MG1 ↔ sun gear (S)"}, COL.mg1, [
    "n = " + rpmTxt(ws) + "   T = " + fmt(op.t1, 1) + " N·m",
    (isHu ? "P mech = " : "P mech = ") + kw(op.p1),
    (isHu ? "P vill. = " : "P elec = ") + kw(op.pe1)]);
  card(760, 488, 175, 82, {hu: "MG2 ↔ gyűrűs kerék (R)", en: "MG2 ↔ ring gear (R)"}, COL.mg2, [
    "n = " + rpmTxt(wr), "T = " + fmt(op.t2, 1) + " N·m",
    "P = " + kw(op.p2) + " (" + (isHu ? "vill. " : "el. ") + kw(op.pe2) + ")"]);
  card(285, 440, 165, 112, {hu: "Bolygómű (k = 2,6)", en: "Planetary (k = 2.6)"}, "#6c757d", [
    "S: " + rpmTxt(ws), "C: " + rpmTxt(we), "R: " + rpmTxt(wr),
