    "T_S : T_R : T_C = 1 : 2,6 : 3,6"]);
  card(630, 682, 215, 70, {hu: "Jármű", en: "Vehicle"}, COL.dark, [
    (isHu ? "F_kerék = " : "F_wheel = ") + fmt(op.fDl, 0) + " N   a = " + fmt(op.aVeh, 2) + " m/s²",
    (isHu ? "F_út = " : "F_road = ") + fmt(abs(vv) > 0.03 ? op.fRoll + op.fAero : 0, 0) + " N" + (abs(op.fGrade) > 1 ? (isHu ? " + emelk. " : " + grade ") + fmt(op.fGrade, 0) + " N" : ""),
    (isHu ? "súrl. fék: " : "friction brake: ") + fmt(op.fFric, 0) + " N"]);

  // ---------- 9. driver panel ----------
  rect(30, 560, 245, 192, {fill: COL.panel, stroke: "#ced4da", lw: 1, radius: 8});
  text(fmt(abs(vv) * 3.6, 0), 120, 618, {size: 46, bold: true, color: COL.dark, align: "center"});
  text("km/h", 120, 640, {size: 13, color: COL.steel, align: "center"});
  text(P.gear, 230, 612, {size: 40, bold: true, color: P.gear === "R" ? COL.fric : COL.mech, align: "center"});
  for (const [xb, val0, col, lab] of [[50, P.acc, COL.mech, {hu: "gáz", en: "accel."}], [200, P.brk, COL.fric, {hu: "fék", en: "brake"}]]) {
    rect(xb, 660, 60, 14, {fill: "#eee", stroke: COL.dark, lw: 1, radius: 3});
    rect(xb, 660, 60 * val0 / 100, 14, {fill: col, stroke: null, radius: 3});
    text(tr(lab) + " " + fmt(val0, 0) + " %", xb + 30, 690, {size: 11, align: "center", color: COL.dark});
  }
  text((isHu ? "EV határ: " : "EV limit: ") + fmt(VEV_MAX * 3.6, 0) + " km/h", 152, 712, {size: 11, color: COL.steel, align: "center"});
  text(op.hold ? (isHu ? "sebesség rögzítve (fékpad)" : "speed held (dyno)") : (P.drv === "demo" ? (isHu ? "automatikus bemutató" : "automatic demo") : (isHu ? "kézi vezetés" : "manual driving")),
    152, 730, {size: 11, color: COL.steel, align: "center"});
  if (P.grade !== 0) text((isHu ? "emelkedő " : "grade ") + fmt(P.grade, 1) + " %", 152, 746, {size: 11, color: COL.steel, align: "center"});

  // ---------- 10. operating mode banner ----------
  const md0 = MODES[op.mode];
  rect(950, 8, 320, 158, {fill: COL.panel, stroke: md0[1], lw: 3, radius: 8});
  rect(950, 8, 320, 30, {fill: md0[1], stroke: null, radius: 8});
  text({hu: "ÜZEMMÓD", en: "OPERATING MODE"}, 960, 28, {size: 12, bold: true, color: "#fff"});
  text(wrapTxt(tr(md0[0]), 38), 960, 58, {size: 16, bold: true, color: md0[1]});
  const nameLines = wrapTxt(tr(md0[0]), 38).split("\n").length;
  text(wrapTxt(tr(md0[2]), 50), 960, 64 + nameLines * 19, {size: 11.5, color: COL.dark});
  if (op.limited) text({hu: "⚠ korlátozva (akku / MG határ)", en: "⚠ limited (battery / MG limit)"}, 1260, 28, {size: 11, bold: true, color: "#fff", align: "right"});

  // ---------- 11. lever (nomogram) diagram, slide 44 ----------
  const lx0 = 985, lx1 = 1240, lxc = lx0 + (lx1 - lx0) * NR / (NS + NR), ly0 = 311, kL = 103 / 6500;
  rect(950, 172, 320, 276, {fill: COL.panel, stroke: "#ced4da", lw: 1, radius: 8});
  text({hu: "Emelőkar-ábra (44. dia): n_s + k·n_r = (k+1)·n_c", en: "Lever diagram (slide 44): n_s + k·n_r = (k+1)·n_c"}, 960, 190, {size: 12, bold: true, color: COL.dark});
  line(lx0 - 15, ly0, lx1 + 15, ly0, {stroke: "#adb5bd", lw: 1});
  for (const [xl, col, lab] of [[lx0, COL.mg1, "S · MG1"], [lxc, COL.eng, "C · ICE"], [lx1, COL.mg2, "R · MG2"]]) {
    line(xl, 202, xl, 420, {stroke: col, lw: 2, alpha: 0.5});
    text(lab, xl, 438, {size: 11, bold: true, color: col, align: "center"});
  }
  for (const yl of [ly0 - 6500 * kL, ly0 + 6500 * kL]) line(lx0 - 8, yl, lx0 + 8, yl, {stroke: COL.fric, lw: 2});
  text({hu: "MG1 határ ±6500", en: "MG1 limit ±6500"}, lx0 + 12, ly0 + 6500 * kL + 4, {size: 10, color: COL.fric});
  const yS = ly0 - ws * K_RPM * kL, yC = ly0 - we * K_RPM * kL, yR = ly0 - wr * K_RPM * kL;
  line(lx0, clamp(yS, 204, 418), lx1, clamp(yR, 204, 418), {stroke: COL.dark, lw: 2.5});
  for (const [xl, yl, col, w0] of [[lx0, yS, COL.mg1, ws], [lxc, yC, COL.eng, we], [lx1, yR, COL.mg2, wr]]) {
    circle(xl, clamp(yl, 204, 418), 6, {fill: col, stroke: "#fff", lw: 1.5});
    text(fmt(w0 * K_RPM, 0), xl + (xl === lx1 ? -8 : 8), clamp(yl, 214, 418) - 8, {size: 11, bold: true, color: col, align: xl === lx1 ? "right" : "left"});
  }

  // ---------- 12. power balance bars ----------
  const bx = 1160, by0 = 474, kB = 62 / 80000;                  // 80 kW = 62 px
  rect(950, 456, 320, 296, {fill: COL.panel, stroke: "#ced4da", lw: 1, radius: 8});
  text({hu: "Teljesítménymérleg (kW)", en: "Power balance (kW)"}, 960, by0 + 2, {size: 12, bold: true, color: COL.dark});
  const pKin = MV * 1.05 * op.aVeh * vv, pRoad = -(op.fRoll + op.fAero) * abs(vv) - op.fGrade * vv;
  const rows = [
    [{hu: "Üzemanyag (kémiai)", en: "Fuel (chemical)"}, op.pFuel, "#6a4c93"],
    [{hu: "Motor tengely", en: "Engine shaft"}, pE, COL.eng],
    [{hu: "MG1 mech. (+motor)", en: "MG1 mech. (+motor)"}, op.p1, COL.mg1],
    [{hu: "MG2 mech. (+motor)", en: "MG2 mech. (+motor)"}, op.p2, COL.mg2],
    [{hu: "Akku (+kisütés)", en: "Battery (+discharge)"}, op.pb, COL.bat],
    [{hu: "Kerekek (hajtáslánc)", en: "Wheels (driveline)"}, op.fDl * vv, COL.mech],
    [{hu: "Súrlódó fék (hő)", en: "Friction brake (heat)"}, -op.fFric * abs(vv), COL.fric],
    [{hu: "Menetellenállás", en: "Road load + grade"}, pRoad, COL.steel],
    [{hu: "Mozgási energia vált.", en: "Kinetic energy change"}, pKin, COL.dark]];
  line(bx, by0 + 12, bx, by0 + 12 + rows.length * 28, {stroke: "#adb5bd", lw: 1});
  rows.forEach(([lab, pw, col], i) => {
    const y = by0 + 18 + i * 28, w = clamp(pw * kB, -66, 66);
    text(lab, 958, y + 13, {size: 10.5, color: COL.dark});
    if (abs(w) > 0.5) rect(w > 0 ? bx : bx + w, y + 2, abs(w), 14, {fill: col, stroke: null, alpha: 0.85});
    text(fmt(pw / 1000, 1), 1264, y + 14, {size: 11, bold: true, color: col, align: "right"});
  });
  text({hu: "kerék + fék + út = mozgási energia változása", en: "wheels + brake + road = change of kinetic energy"}, 1110, 745, {size: 10, color: COL.steel, align: "center"});

  // ---------- 13. readouts and graphs ----------
  show({hu: "Üzemmód", en: "Operating mode"}, tr(md0[0]), "");
  show({hu: "Járműsebesség", en: "Vehicle speed"}, vv * 3.6, "km/h", 1);
  show({hu: "Gyorsulás", en: "Acceleration"}, op.aVeh, "m/s²", 2);
  show({hu: "Motor n / T / P", en: "Engine n / T / P"}, fmt(we * K_RPM, 0) + " 1/min / " + fmt(teAct, 1) + " N·m / " + fmt(pE / 1000, 1) + " kW", "");
  show({hu: "MG1 n / T / P", en: "MG1 n / T / P"}, fmt(ws * K_RPM, 0) + " 1/min / " + fmt(op.t1, 1) + " N·m / " + fmt(op.p1 / 1000, 1) + " kW", "");
  show({hu: "MG2 n / T / P", en: "MG2 n / T / P"}, fmt(wr * K_RPM, 0) + " 1/min / " + fmt(op.t2, 1) + " N·m / " + fmt(op.p2 / 1000, 1) + " kW", "");
  show({hu: "Gyűrűs kerék nyomatéka (motor + MG2)", en: "Ring gear torque (engine + MG2)"}, fmt(op.tE2R, 1) + " + " + fmt(op.t2, 1) + " = " + fmt(op.tRing, 1), "N·m");
  show({hu: "Akku U / I / P", en: "Battery U / I / P"}, fmt(op.ub, 1) + " V / " + fmt(op.ib, 1) + " A / " + fmt(op.pb / 1000, 1) + " kW", "");
  show({hu: "Akku határ: kisütés / töltés", en: "Battery limit: discharge / charge"}, fmt(op.pDis / 1000, 1) + " / " + fmt(op.pChgL / 1000, 1), "kW");
  show({hu: "Kerékerő: kért / leadott", en: "Wheel force: requested / delivered"}, fmt(op.fReq, 0) + " / " + fmt(op.fDl, 0), "N");
  show({hu: "Súrlódó fék", en: "Friction brakes"}, op.fFric, "N", 0);
  show({hu: "Pillanatnyi fogyasztás", en: "Instant fuel consumption"}, abs(vv) > 1 ? op.fuelGs / 745 / abs(vv) * 1e5 : 0, "L/100 km", 1);
  show({hu: "EV sebességhatár (MG1 6500 1/min)", en: "EV speed limit (MG1 6500 1/min)"}, VEV_MAX * 3.6, "km/h", 1);
  plot({hu: "n motor", en: "n engine"}, we * K_RPM, {unit: "1/min", color: COL.eng, group: "n"});
  plot("n MG1", ws * K_RPM, {unit: "1/min", color: COL.mg1, group: "n"});
  plot("n MG2", wr * K_RPM, {unit: "1/min", color: COL.mg2, group: "n"});
  plot({hu: "P motor", en: "P engine"}, pE / 1000, {unit: "kW", color: COL.eng, group: "P"});
  plot("P MG1", op.p1 / 1000, {unit: "kW", color: COL.mg1, group: "P"});
  plot("P MG2", op.p2 / 1000, {unit: "kW", color: COL.mg2, group: "P"});
  plot({hu: "P akku", en: "P battery"}, op.pb / 1000, {unit: "kW", color: COL.bat, group: "P"});
  plot("v", vv * 3.6, {unit: "km/h", color: COL.dark, group: "v"});
  plot("SOC", socS * 100, {unit: "%", color: COL.mech, group: "soc", min: 20, max: 100});
  val({v_kmh: vv * 3.6, n_e: we * K_RPM, n_mg1: ws * K_RPM, n_mg2: wr * K_RPM, P_e: pE / 1000, P_mg1: op.p1 / 1000, P_mg2: op.p2 / 1000, P_batt: op.pb / 1000, SOC: socS * 100});
});
